pub(crate) const NT_NNH: i32 = 24;
pub(crate) fn nt_last_word(wd: &mut crate::port::Cells, ln: &mut crate::port::Cells, l: i32) -> i32 {
    let w0: i32 = ln_get(ln, l, lh_first());
    let mut i: i32 = (w0 + ln_get(ln, l, lh_count())) - 1;
    while i >= w0 {
        if ls_wl(wd, i) > 0 {
            return i;
        }
        i -= 1;
    }
    return -1;
}
pub(crate) fn nt_nh_match(wd: &mut crate::port::Cells, ln: &mut crate::port::Cells, et: &mut crate::port::Cells, l: i32, e: i32) -> i32 {
    // 1 when the words of line l, joined by one space, with a colon or a full stop at their end dropped, spell entry e of
    // the notes headings, in any case.
    let off: i32 = NT_NHI[(e * 2) as usize];
    let n: i32 = NT_NHI[((e * 2) + 1) as usize];
    let lw: i32 = nt_last_word(wd, ln, l);
    let w0: i32 = ln_get(ln, l, lh_first());
    let wn: i32 = ln_get(ln, l, lh_count());
    let mut k: i32 = 0;
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut first: i32 = 1;
    if lw < 0 {
        return 0;
    }
    while i < wn {
        let w: i32 = w0 + i;
        let tl: i32 = ls_wl(wd, w);
        if tl > 0 {
            if first == 0 {
                if (k >= n) || (NT_NH[(off + k) as usize] != 32) {
                    return 0;
                }
                k += 1;
            }
            first = 0;
            j = 0;
            while j < tl {
                let c: i32 = ls_wc(wd, et, w, j);
                if (w == lw) && (j == (tl - 1)) && ((c == 58) || (c == 46)) {
                    j += 1;
                } else {
                    if (k >= n) || (nt_lower(c) != NT_NH[(off + k) as usize]) {
                        return 0;
                    }
                    k += 1;
                    j += 1;
                }
            }
        }
        i += 1;
    }
    if k == n {
        return 1;
    }
    return 0;
}
pub(crate) fn nt_notes_heading(wd: &mut crate::port::Cells, ln: &mut crate::port::Cells, et: &mut crate::port::Cells, l: i32) -> i32 {
    let mut e: i32 = 0;
    while e < NT_NNH {
        if nt_nh_match(wd, ln, et, l, e) == 1 {
            return 1;
        }
        e += 1;
    }
    return 0;
}
pub(crate) fn nt_first_notes_heading(wd: &mut crate::port::Cells, ln: &mut crate::port::Cells, et: &mut crate::port::Cells, hc: &mut crate::port::Cells, rf: &mut crate::port::Cells) -> i32 {
    // The first heading line that says `Notes` after the first reference there is; -1 when there is none (or no reference).
    if crate::port::cells_len(rf) == 0 {
        return -1;
    }
    let n: i32 = ln_count(ln);
    let mut h: i32 = crate::port::cells_at(rf, 3) + 1;
    while h < n {
        if ls_upright(ln, h) && (hd_level(hc, h) > 0) && (nt_notes_heading(wd, ln, et, h) == 1) {
            return h;
        }
        h += 1;
    }
    return -1;
}
pub(crate) fn nt_nth_ref(rf: &mut crate::port::Cells, n: i32) -> i32 {
    // The row of the n-th (from 0) reference that nothing has claimed (state 0); -1 when there are fewer.
    let nr: i32 = crate::port::cells_len(rf) / NT_RF;
    let mut r: i32 = 0;
    let mut seen: i32 = 0;
    while r < nr {
        if crate::port::cells_at(rf, (r * NT_RF) + 7) == 0 {
            if seen == n {
                return r;
            }
            seen += 1;
        }
        r += 1;
    }
    return -1;
}
pub(crate) fn nt_put_mark(mut et: &mut crate::port::Cells, mk: &mut crate::port::Cells, ms: i32, ml: i32) -> i32 {
    let mut i: i32 = 0;
    while i < ml {
        crate::port::cells_push(et, crate::port::cells_at(mk, ms + i));
        i += 1;
    }
    return 0;
}
pub(crate) fn nt_wrap_note(mut wd: &mut crate::port::Cells, mut et: &mut crate::port::Cells, mk: &mut crate::port::Cells, w: i32, ms: i32, ml: i32, role: i32) -> i32 {
    // Word w begins with an `S_NOTE` group (the role) whose text is the marker mk[ms, ms+ml), and keeps its own text.
    let s: i32 = ls_wrap_begin(et, ls_s_note(), role, -1);
    nt_put_mark(et, mk, ms, ml);
    ls_wrap_end(et);
    ls_copy_word(et, wd, w, 0);
    ls_wrap_set(wd, et, w, s);
    return 0;
}
pub(crate) fn nt_claim(mut wd: &mut crate::port::Cells, mut et: &mut crate::port::Cells, ln: &mut crate::port::Cells, mut hc: &mut crate::port::Cells, rf: &mut crate::port::Cells, mk: &mut crate::port::Cells, b: i32, k: i32) -> i32 {
    // Line b starts the k-th note under a heading: an endnote whose marker is the k-th reference nothing claimed.
    let r: i32 = nt_nth_ref(rf, k);
    let w: i32 = ls_first_word(wd, ln, b);
    if (r >= 0) && (w >= 0) {
        nt_wrap_note(wd, et, mk, w, crate::port::cells_at(rf, (r * NT_RF) + 5), crate::port::cells_at(rf, (r * NT_RF) + 6), 5);
        ls_put(hc, b, ls_k_flags(), ls_f_note());
    }
    return 0;
}
pub(crate) fn nt_walk(mut wd: &mut crate::port::Cells, mut et: &mut crate::port::Cells, ln: &mut crate::port::Cells, sf: &mut crate::port::Cells, mut hc: &mut crate::port::Cells, rf: &mut crate::port::Cells, mk: &mut crate::port::Cells, h: i32, doit: i32) -> i32 {
    // The notes under the heading line h: the first line below it and every line below that starts after more than one and
    // a half line gaps of whitespace. With doit 1 each one is rewritten as an endnote whose marker is the next of the
    // references nothing has claimed. Answers how many there are.
    let med: i32 = st_hget(sf, sfh_gap());
    let mut b: i32 = st_get(sf, h, sfk_below());
    let mut k: i32 = 0;
    let mut steps: i32 = 0;
    let mut first: i32 = 1;
    let mut start: i32 = 0;
    while (b >= 0) && (steps < 400) {
        if (hd_level(hc, b) > 0) || !ls_upright(ln, b) || (ls_get(hc, b, ls_k_flags()) != 0) || (ln_get(ln, b, lh_page()) != ln_get(ln, h, lh_page())) {
            b = -1;
        } else {
            start = first;
            let g: i32 = st_get(sf, b, sfk_gap_above());
            let hb: i32 = st_get(sf, b, sfk_height());
            if ((g * 2) > (med * 3)) && (((g - med) * 8) > hb) {
                start = 1;
            }
            if start == 1 {
                if doit == 1 {
                    nt_claim(wd, et, ln, hc, rf, mk, b, k);
                }
                k += 1;
            }
            first = 0;
            b = st_get(sf, b, sfk_below());
        }
        steps += 1;
    }
    return k;
}
pub(crate) fn nt_markerless(mut wd: &mut crate::port::Cells, mut et: &mut crate::port::Cells, ln: &mut crate::port::Cells, sf: &mut crate::port::Cells, mut hc: &mut crate::port::Cells, mut rf: &mut crate::port::Cells, mk: &mut crate::port::Cells) -> i32 {
    // References left over (a superscript marker no body claimed) and a heading that says `Notes` after them: the lines
    // under it that start a note, as many as there are references, are the endnotes, the printed marker being none; the
    // markers are the references' own, in order. A different count leaves everything as it is.
    let nr: i32 = crate::port::cells_len(rf) / NT_RF;
    let n: i32 = ln_count(ln);
    let mut r: i32 = 0;
    let mut un: i32 = 0;
    let mut fl: i32 = -1;
    let mut h: i32 = 0;
    let mut k: i32 = 0;
    while r < nr {
        if crate::port::cells_at(rf, (r * NT_RF) + 7) == 0 {
            if fl < 0 {
                fl = crate::port::cells_at(rf, (r * NT_RF) + 3);
            }
            un += 1;
        }
        r += 1;
    }
    if (un == 0) || (un > 400) {
        return 0;
    }
    h = fl + 1;
    while h < n {
        if ls_upright(ln, h) && (hd_level(hc, h) > 0) && (nt_notes_heading(wd, ln, et, h) == 1) {
            k = nt_walk(wd, et, ln, sf, hc, rf, mk, h, 0);
            if k == un {
                nt_walk(wd, et, ln, sf, hc, rf, mk, h, 1);
                r = 0;
                while r < nr {
                    if crate::port::cells_at(rf, (r * NT_RF) + 7) == 0 {
                        crate::port::cells_set(rf, (r * NT_RF) + 7, 2);
                    }
                    r += 1;
                }
                return k;
            }
        }
        h += 1;
    }
    return 0;
}
pub(crate) fn nt_apply_bodies(mut wd: &mut crate::port::Cells, mut et: &mut crate::port::Cells, gl: &mut crate::port::Cells, ln: &mut crate::port::Cells, mut nb: &mut crate::port::Cells, mk: &mut crate::port::Cells, mut rf: &mut crate::port::Cells, mut hc: &mut crate::port::Cells) -> i32 {
    // Rewrite the first word of every confirmed note body: its marker leaves the text, an `S_NOTE` group (the role: 4 a
    // footnote, 5 an endnote) takes its place. The line's row says a note starts there.
    let nn: i32 = crate::port::cells_len(nb) / NT_NB;
    let mut i: i32 = 0;
    while i < nn {
        let b: i32 = i * NT_NB;
        let st: i32 = crate::port::cells_at(nb, b + 7);
        if (st == 1) || (st == 2) {
            let l: i32 = crate::port::cells_at(nb, b);
            let w: i32 = crate::port::cells_at(nb, b + 2);
            let kind: i32 = crate::port::cells_at(nb, b + 3);
            let ts: i32 = wd_get(wd, w, hd_tstart());
            let tl: i32 = wd_get(wd, w, hd_tlen());
            let s: i32 = ls_wrap_begin(et, ls_s_note(), st + 3, -1);
            nt_put_mark(et, mk, crate::port::cells_at(nb, b + 5), crate::port::cells_at(nb, b + 6));
            ls_wrap_end(et);
            if kind == 1 {
                let mut j: i32 = crate::port::cells_at(nb, b + 4);
                while j < (ts + tl) {
                    crate::port::cells_push(et, crate::port::cells_at(et, j));
                    j += 1;
                }
            }
            ls_wrap_set(wd, et, w, s);
            ls_put(hc, l, ls_k_flags(), ls_f_note());
            // references in this very word are left alone
            let mut r: i32 = 0;
            while r < (crate::port::cells_len(rf) / NT_RF) {
                if crate::port::cells_at(rf, r * NT_RF) == w {
                    crate::port::cells_set(rf, (r * NT_RF) + 7, 9);
                }
                r += 1;
            }
        }
        i += 1;
    }
    return 0;
}
pub(crate) fn nt_apply_refs(mut wd: &mut crate::port::Cells, mut et: &mut crate::port::Cells, gl: &mut crate::port::Cells, rf: &mut crate::port::Cells, mk: &mut crate::port::Cells) -> i32 {
    // Rewrite every word that holds a confirmed reference: each reference becomes an `S_REF` group inside the word's
    // text, the marker as the group's text.
    let nr: i32 = crate::port::cells_len(rf) / NT_RF;
    let mut i: i32 = 0;
    let mut i1: i32 = 0;
    while i < nr {
        i1 = i + 1;
        while (i1 < nr) && (crate::port::cells_at(rf, i1 * NT_RF) == crate::port::cells_at(rf, i * NT_RF)) {
            i1 += 1;
        }
        let w: i32 = crate::port::cells_at(rf, i * NT_RF);
        let ts: i32 = wd_get(wd, w, hd_tstart());
        let tl: i32 = wd_get(wd, w, hd_tlen());
        let mut any: i32 = 0;
        let mut j: i32 = i;
        while j < i1 {
            if (crate::port::cells_at(rf, (j * NT_RF) + 7) == 1) || (crate::port::cells_at(rf, (j * NT_RF) + 7) == 2) {
                any = 1;
            }
            j += 1;
        }
        if any == 1 {
            let s: i32 = crate::port::cells_len(et);
            let mut p: i32 = ts;
            j = i;
            while j < i1 {
                if (crate::port::cells_at(rf, (j * NT_RF) + 7) == 1) || (crate::port::cells_at(rf, (j * NT_RF) + 7) == 2) {
                    let a: i32 = crate::port::cells_at(rf, (j * NT_RF) + 1);
                    let b: i32 = crate::port::cells_at(rf, (j * NT_RF) + 2);
                    if (a >= p) && (b <= (ts + tl)) && (b > a) {
                        let mut q: i32 = p;
                        while q < a {
                            crate::port::cells_push(et, crate::port::cells_at(et, q));
                            q += 1;
                        }
                        ls_wrap_begin(et, ls_s_ref(), 0, -1);
                        nt_put_mark(et, mk, crate::port::cells_at(rf, (j * NT_RF) + 5), crate::port::cells_at(rf, (j * NT_RF) + 6));
                        ls_wrap_end(et);
                        p = b;
                    }
                }
                j += 1;
            }
            while p < (ts + tl) {
                crate::port::cells_push(et, crate::port::cells_at(et, p));
                p += 1;
            }
            ls_wrap_set(wd, et, w, s);
        }
        i = i1;
    }
    return 0;
}
pub fn nt_analyze(mut wd: &mut crate::port::Cells, mut ln: &mut crate::port::Cells, mut et: &mut crate::port::Cells, gl: &mut crate::port::Cells, sf: &mut crate::port::Cells, sc: &mut crate::port::Cells, pages: &mut crate::port::Cells, mut hc: &mut crate::port::Cells, mut rf: &mut crate::port::Cells, mut nb: &mut crate::port::Cells, mut mk: &mut crate::port::Cells, tw: &mut crate::port::Cells, mut ix: &mut crate::port::Cells) -> i32 {
    // Find the captions, the note bodies and the references that point at them, and mark them (see the module's head).
    // `rf`, `nb`, `mk` are scratch. Answers the number of captions plus note bodies.
    if ls_open(hc) == 0 {
        return 0;
    }
    ls_taint(wd, ln, hc, tw);
    let n: i32 = ln_count(ln);
    let mut l: i32 = 0;
    let mut nhl: i32 = -1;
    let mut found: i32 = 0;
    // captions first: a caption is never a note body. Found first (flag 8, nothing rewritten), then the candidates that
    // stand in a run (a list of figures: entries one under another, a line gap apart) are let go, then the rest rewritten.
    while l < n {
        if ls_upright(ln, l) && (hd_level(hc, l) == 0) && (ls_get(hc, l, ls_k_flags()) == 0) && (nt_caption(wd, et, ln, sf, sc, hc, l, 0) == 1) {
            ls_put(hc, l, ls_k_flags(), ls_f_cap());
        }
        l += 1;
    }
    crate::port::cells_drop(rf, 0);
    l = 0;
    while l < n {
        if (ls_get(hc, l, ls_k_flags()) == ls_f_cap()) || (ls_get(hc, l, ls_k_flags()) == 64) {
            crate::port::cells_push(rf, l);
        }
        l += 1;
    }
    l = 0;
    while l < n {
        if ls_get(hc, l, ls_k_flags()) == ls_f_cap() {
            if (nt_in_run(sf, ln, hc, l) == 1) || ((nt_toc_like(wd, ln, et, sf, l) == 1) || ((nt_in_prose(ln, sf, sc, l) == 1) || (nt_running_label(wd, ln, et, hc, pages, l, rf) == 1))) {
                ls_put(hc, l, ls_k_flags(), 64);
            }
        }
        l += 1;
    }
    l = 0;
    while l < n {
        let fl: i32 = ls_get(hc, l, ls_k_flags());
        if (fl == ls_f_cap()) || (fl == 64) {
            ls_put(hc, l, ls_k_flags(), 0);
            if fl == ls_f_cap() {
                found += nt_caption(wd, et, ln, sf, sc, hc, l, 1);
            }
        }
        l += 1;
    }
    nt_scan(wd, ln, et, gl, sf, pages, hc, rf, nb, mk);
    nhl = nt_first_notes_heading(wd, ln, et, hc, rf);
    crate::port::cells_drop(ix, 0);
    nt_match(wd, et, ln, sf, rf, nb, mk, ix, nhl);
    nt_markerless(wd, et, ln, sf, hc, rf, mk);
    l = 0;
    while l < (crate::port::cells_len(nb) / NT_NB) {
        if (crate::port::cells_at(nb, (l * NT_NB) + 7) == 1) || (crate::port::cells_at(nb, (l * NT_NB) + 7) == 2) {
            found += 1;
        }
        l += 1;
    }
    nt_apply_bodies(wd, et, gl, ln, nb, mk, rf, hc);
    nt_apply_refs(wd, et, gl, rf, mk);
    return found;
}
